$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$api = Join-Path $root 'apps\api'
if (Get-NetTCPConnection -LocalPort 3000 -State Listen -ErrorAction SilentlyContinue) { throw 'Pare somente a API com Ctrl+C antes de executar. Mantenha o Cloudflared aberto.' }
$servicePath = Join-Path $api 'src\wallet\asaas-payout.service.ts'
$controllerPath = Join-Path $api 'src\wallet\asaas-payout.controller.ts'
$helperPath = Join-Path $api 'src\wallet\asaas-authorization.ts'
$testPath = Join-Path $api 'src\wallet\asaas-authorization.spec.ts'
$envPath = Join-Path $api '.env'
$service = [IO.File]::ReadAllText($servicePath)
$controller = [IO.File]::ReadAllText($controllerPath)
$envText = [IO.File]::ReadAllText($envPath)
if ($envText -notmatch '(?m)^ASAAS_ENVIRONMENT\s*=\s*["'']?sandbox["'']?\s*$') { throw 'Este instalador e exclusivo do Sandbox.' }
$serviceAnchor = '  async adminReconcile('
$controllerAnchor = "  @Get('status')"
$serviceAddition = @'
  // porto-asaas-authorization-v1
  async authorize(token: string | undefined, body: unknown) {
    return authorizeAsaasWithdrawal(this.db, token, body);
  }
'@
$controllerAddition = @'
  // porto-asaas-authorization-v1
  @Post('authorize') @HttpCode(200)
  authorize(@Headers('asaas-access-token') token: string | undefined, @Body() body: unknown) {
    return this.payouts.authorize(token, body);
  }
'@
if ($service -notmatch 'porto-asaas-authorization-v1') {
  if (($service.Split(@($serviceAnchor), [StringSplitOptions]::None).Count -ne 2) -or $service -match 'async authorize\(') { throw 'Servico diferente do esperado; nenhum arquivo alterado.' }
  $service = "import { authorizeAsaasWithdrawal } from './asaas-authorization.js';" + [Environment]::NewLine + $service.Replace($serviceAnchor, $serviceAddition + [Environment]::NewLine + $serviceAnchor)
}
if ($controller -notmatch 'porto-asaas-authorization-v1') {
  if (($controller.Split(@($controllerAnchor), [StringSplitOptions]::None).Count -ne 2) -or $controller -match "Post\('authorize'\)") { throw 'Controller diferente do esperado; nenhum arquivo alterado.' }
  $controller = $controller.Replace($controllerAnchor, $controllerAddition + [Environment]::NewLine + $controllerAnchor)
}
$backup = Join-Path $env:TEMP ('porto-asaas-autorizacao-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $backup | Out-Null
$paths = @($servicePath,$controllerPath,$helperPath,$testPath,$envPath)
$existed = @{}
foreach ($path in $paths) {
  $existed[$path] = Test-Path $path
  if ($existed[$path]) { Copy-Item $path (Join-Path $backup ([IO.Path]::GetFileName($path))) }
}
$utf8 = New-Object Text.UTF8Encoding($false)
Push-Location $api
try {
  [IO.File]::WriteAllText($servicePath,$service,$utf8)
  [IO.File]::WriteAllText($controllerPath,$controller,$utf8)
  [IO.File]::WriteAllBytes($helperPath,[Convert]::FromBase64String(''))
  [IO.File]::WriteAllBytes($testPath,[Convert]::FromBase64String(''))
  npm test -- src/wallet/asaas-authorization.spec.ts
  if ($LASTEXITCODE -ne 0) { throw 'Testes de autorizacao falharam.' }
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build da API falhou.' }
  if ($envText -notmatch '(?m)^ASAAS_AUTHORIZATION_TOKEN\s*=') {
    $bytes = New-Object byte[] 32
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
    $token = [BitConverter]::ToString($bytes).Replace('-','').ToLowerInvariant()
    [IO.File]::AppendAllText($envPath,[Environment]::NewLine + 'ASAAS_AUTHORIZATION_TOKEN=' + $token + [Environment]::NewLine,$utf8)
  } else {
    $match = [regex]::Match($envText,'(?m)^ASAAS_AUTHORIZATION_TOKEN\s*=\s*["'']?([^\s"'']{32,255})["'']?\s*$')
    if (!$match.Success) { throw 'ASAAS_AUTHORIZATION_TOKEN existente invalido; corrija sem expor o segredo.' }
  }
  Write-Host 'Autorizacao Sandbox instalada. Rota: POST /api/wallet/asaas/authorize'
  Write-Host "Backup: $backup"
  Write-Host 'Reinicie a API. Ainda sera necessario configurar esta rota no Asaas.'
} catch {
  foreach ($path in $paths) {
    if ($existed[$path]) { Copy-Item (Join-Path $backup ([IO.Path]::GetFileName($path))) $path -Force }
    elseif (Test-Path $path) { Remove-Item $path -Force }
  }
  Write-Host 'Arquivos restaurados. Nao ative a autorizacao no Asaas.'
  throw
} finally { Pop-Location }
